    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = {0}

    for score in scores:
        new_dp = dp.copy()
        for s in dp:
            if s + score == target:
                return "YES"
            new_dp.add(s + score)
        dp = new_dp

    return "NO"

